from __future__ import annotations

"""
Single-file source bundle for the completed WC2018+WC2022 EDA report.

Usage:
    python wc2018_2022_final_report_source.py

Inputs expected in the same folder:
    wc2018_shots.csv
    wc2022_shots.csv

Outputs regenerated:
    wc2018_2022_shots.csv
    wc2018_2022_eda_integrated_report.md
    wc2018_2022_eda_integrated_report.html
    outputs/wc2018_2022_attack_pressure_eda/
    outputs/wc2018_2022_high_level_analysis/

This file bundles the final report pipeline and its local helper modules:
    - viz_theme.py
    - eda_attack_pressure.py
    - eda_high_level_questions.py
    - build_wc2018_2022_report.py
"""

import sys
import types
from pathlib import Path


def _install_bundled_module(name: str, source: str, filename: str):
    module = types.ModuleType(name)
    module.__file__ = str(Path(__file__).resolve().parent / filename)
    sys.modules[name] = module
    exec(compile(source, filename, 'exec'), module.__dict__)
    return module


# ---- bundled source: viz_theme.py ----
_VIZ_THEME_SOURCE = 'from __future__ import annotations\n\nfrom collections.abc import Iterable\n\nimport matplotlib.pyplot as plt\nfrom matplotlib.colors import LinearSegmentedColormap\n\n\nBG = "#11281d"\nPANEL = "#173825"\nPANEL2 = "#1b3b28"\nGRID = "#315238"\nLIME = "#9ccc5a"\nLIME_LIGHT = "#c8e879"\nLIME_DARK = "#356d17"\nTEXT = "#f4f7ef"\nMUTED = "#a7b9a6"\nTEAL = "#2f8f7d"\nBLUE_GREEN = "#4f9aa7"\nGOLD = "#d9a441"\nNEGATIVE = "#d46a6a"\n\nBAR = LIME\nBAR_DARK = LIME_DARK\nBAR_ALT = "#7fb34d"\nBAR_MUTED = "#5d8f44"\nLINE_COLORS = [LIME, BLUE_GREEN, GOLD, TEAL, LIME_LIGHT, MUTED]\nSTACK_COLORS = {\n    "complete": LIME,\n    "close_contested": "#5fa8b4",\n    "far_clean": GOLD,\n    "low_value": "#6f7f73",\n}\nXG_CMAP = LinearSegmentedColormap.from_list(\n    "dsl_xg_lime",\n    [PANEL, "#2f5f2a", LIME, LIME_LIGHT],\n)\nXG_CMAP_R = LinearSegmentedColormap.from_list(\n    "dsl_xg_lime_r",\n    [LIME_LIGHT, LIME, "#2f5f2a", PANEL],\n)\n\n\ndef apply_theme(fig, axes=None) -> None:\n    """Apply the dark green Canva-style theme to a matplotlib figure."""\n\n    fig.patch.set_facecolor(BG)\n    target_axes = _flatten_axes(axes) if axes is not None else fig.axes\n    for ax in target_axes:\n        ax.set_facecolor(BG)\n        ax.title.set_color(TEXT)\n        ax.xaxis.label.set_color(TEXT)\n        ax.yaxis.label.set_color(TEXT)\n        ax.tick_params(colors=TEXT)\n        for spine in ax.spines.values():\n            spine.set_color(GRID)\n        for text in ax.texts:\n            if _is_dark_text(text.get_color()):\n                text.set_color(TEXT)\n            bbox = text.get_bbox_patch()\n            if bbox is not None:\n                bbox.set_facecolor(PANEL2)\n                bbox.set_edgecolor(GRID)\n                bbox.set_alpha(0.94)\n        legend = ax.get_legend()\n        if legend is not None:\n            frame = legend.get_frame()\n            frame.set_facecolor(PANEL)\n            frame.set_edgecolor(GRID)\n            frame.set_alpha(0.96)\n            if legend.get_title() is not None:\n                legend.get_title().set_color(TEXT)\n            for text in legend.get_texts():\n                text.set_color(TEXT)\n        for child in ax.get_children():\n            label = getattr(child, "get_label", lambda: "")()\n            if isinstance(label, str) and label.startswith("<colorbar"):\n                child.tick_params(colors=TEXT)\n    for text in fig.texts:\n        if _is_dark_text(text.get_color()):\n            text.set_color(TEXT)\n\n\ndef save_dark(fig, path, *, dpi=180, bbox_inches="tight") -> None:\n    fig.savefig(path, dpi=dpi, bbox_inches=bbox_inches, facecolor=fig.get_facecolor())\n\n\ndef _flatten_axes(axes) -> list:\n    if hasattr(axes, "ravel"):\n        return list(axes.ravel())\n    if isinstance(axes, Iterable) and not hasattr(axes, "plot"):\n        out = []\n        for item in axes:\n            out.extend(_flatten_axes(item))\n        return out\n    return [axes]\n\n\ndef _is_dark_text(color) -> bool:\n    if color is None:\n        return True\n    color_str = str(color).lower()\n    return color_str in {"black", "k", "#000000", "#111111", "#111827", "#102018", "#374151", "0.0"}\n'

# ---- bundled source: eda_attack_pressure.py ----
_EDA_ATTACK_PRESSURE_SOURCE = 'from pathlib import Path\nimport json\n\nimport numpy as np\nimport pandas as pd\n\nimport matplotlib\n\nmatplotlib.use("Agg")\nimport matplotlib.pyplot as plt\nfrom matplotlib.patches import Arc, Rectangle\n\nimport viz_theme as vt\n\n\nDATA_PATH = Path("wc2022_shots.csv")\nOUT_DIR = Path("outputs") / "wc2022_attack_pressure_eda"\n\n\nATTACK_ORDER = [\n    "cutback",\n    "central_penetration",\n    "wide_cross",\n    "fast_counter",\n    "high_turnover",\n    "slow_possession",\n    "set_piece",\n    "other",\n]\n\nATTACK_LABELS = {\n    "cutback": "컷백",\n    "central_penetration": "중앙 침투",\n    "wide_cross": "와이드 크로스",\n    "fast_counter": "빠른 역습",\n    "high_turnover": "높은 위치 탈취",\n    "slow_possession": "긴 점유",\n    "set_piece": "세트피스",\n    "other": "기타",\n}\n\nLAST_PASS_LABELS = {\n    "through_ball": "스루패스",\n    "cross": "크로스",\n    "no_key_pass": "키패스 없음",\n    "cutback": "컷백",\n    "central_pass": "중앙 패스",\n    "other": "기타",\n}\n\n\ndef ensure_out_dir() -> None:\n    OUT_DIR.mkdir(parents=True, exist_ok=True)\n\n\ndef set_korean_plot_style() -> None:\n    plt.rcParams["font.family"] = ["Malgun Gothic", "Noto Sans KR", "DejaVu Sans"]\n    plt.rcParams["axes.unicode_minus"] = False\n\n\ndef mean_ci(frame: pd.DataFrame, group_col: str, value_col: str) -> pd.DataFrame:\n    grouped = frame.groupby(group_col, dropna=False, observed=False)[value_col]\n    out = grouped.agg(["count", "mean", "std"]).reset_index()\n    out["se"] = out["std"] / np.sqrt(out["count"].clip(lower=1))\n    out["ci_low"] = out["mean"] - 1.96 * out["se"]\n    out["ci_high"] = out["mean"] + 1.96 * out["se"]\n    return out\n\n\ndef summarize_attack_types(df: pd.DataFrame) -> pd.DataFrame:\n    summary = (\n        df.groupby("attack_type", observed=False)\n        .agg(\n            shots=("shot_id", "size"),\n            goals=("is_goal", "sum"),\n            total_xg=("xg", "sum"),\n            mean_xg=("xg", "mean"),\n            median_xg=("xg", "median"),\n            goal_rate=("is_goal", "mean"),\n            avg_shot_dist_m=("shot_dist_to_goal_m", "mean"),\n            avg_nearest_def_m=("nearest_def_dist_m", "mean"),\n            avg_def_between=("def_between_ball_goal", "mean"),\n            avg_def_in_box=("def_in_box", "mean"),\n            avg_duration_s=("attack_duration_s", "mean"),\n            avg_n_pass=("n_pass", "mean"),\n            avg_x_progression=("x_progression", "mean"),\n        )\n        .reset_index()\n    )\n    ci = mean_ci(df, "attack_type", "xg")[\n        ["attack_type", "se", "ci_low", "ci_high"]\n    ]\n    summary = summary.merge(ci, on="attack_type", how="left")\n    summary["attack_type"] = pd.Categorical(\n        summary["attack_type"], categories=ATTACK_ORDER, ordered=True\n    )\n    return summary.sort_values(["attack_type"])\n\n\ndef summarize_last_pass(df: pd.DataFrame) -> pd.DataFrame:\n    work = df.copy()\n    work["last_pass_type_filled"] = work["last_pass_type"].fillna("no_key_pass")\n    summary = (\n        work.groupby("last_pass_type_filled", observed=False)\n        .agg(\n            shots=("shot_id", "size"),\n            goals=("is_goal", "sum"),\n            mean_xg=("xg", "mean"),\n            median_xg=("xg", "median"),\n            goal_rate=("is_goal", "mean"),\n            avg_shot_dist_m=("shot_dist_to_goal_m", "mean"),\n            avg_nearest_def_m=("nearest_def_dist_m", "mean"),\n        )\n        .reset_index()\n        .sort_values("mean_xg", ascending=False)\n    )\n    return summary\n\n\ndef add_bins(df: pd.DataFrame) -> pd.DataFrame:\n    work = df.copy()\n    work["shot_distance_bin"] = pd.cut(\n        work["shot_dist_to_goal_m"],\n        bins=[0, 12, 20, np.inf],\n        labels=["근거리(<12m)", "중거리(12-20m)", "장거리(20m+)"],\n        right=False,\n    )\n    work["nearest_def_bin"] = pd.cut(\n        work["nearest_def_dist_m"],\n        bins=[0, 1, 2, 3, 5, np.inf],\n        labels=["0-1m", "1-2m", "2-3m", "3-5m", "5m+"],\n        right=False,\n    )\n    work["duration_bin"] = pd.cut(\n        work["attack_duration_s"],\n        bins=[-0.1, 10, 20, 40, np.inf],\n        labels=["0-10s", "10-20s", "20-40s", "40s+"],\n    )\n    return work\n\n\ndef baseline_adjusted_residuals(df: pd.DataFrame) -> pd.DataFrame:\n    features = [\n        "shot_dist_to_goal_m",\n        "shot_x",\n        "shot_y",\n        "nearest_def_dist_m",\n        "def_within_2m",\n        "def_between_ball_goal",\n        "def_in_box",\n        "gk_dist_from_goalline_m",\n        "gk_lateral_offset_m",\n    ]\n    work = df.copy()\n    work["under_pressure_num"] = work["under_pressure"].fillna(False).astype(int)\n    work["first_time_num"] = work["first_time"].fillna(False).astype(int)\n    features += ["under_pressure_num", "first_time_num"]\n\n    model_df = work.dropna(subset=features + ["xg"]).copy()\n    x_num = model_df[features].astype(float)\n    x_num = (x_num - x_num.mean()) / x_num.std(ddof=0).replace(0, 1)\n    design = pd.concat(\n        [\n            pd.Series(1.0, index=model_df.index, name="intercept"),\n            x_num,\n            pd.get_dummies(model_df["body_part"], prefix="body", drop_first=True),\n            pd.get_dummies(model_df["shot_type"], prefix="type", drop_first=True),\n        ],\n        axis=1,\n    ).astype(float)\n    y = model_df["xg"].to_numpy(dtype=float)\n    beta, *_ = np.linalg.lstsq(design.to_numpy(), y, rcond=None)\n    model_df["xg_baseline_pred"] = design.to_numpy() @ beta\n    model_df["xg_adj_residual"] = model_df["xg"] - model_df["xg_baseline_pred"]\n    return model_df\n\n\ndef draw_pitch(ax) -> None:\n    ax.set_xlim(60, 120)\n    ax.set_ylim(0, 80)\n    ax.set_aspect("equal")\n    ax.axis("off")\n    color = vt.GRID\n    ax.add_patch(Rectangle((60, 0), 60, 80, fill=False, ec=color, lw=1.0))\n    ax.plot([120, 120], [36, 44], color=color, lw=3)\n    ax.add_patch(Rectangle((102, 18), 18, 44, fill=False, ec=color, lw=1.0))\n    ax.add_patch(Rectangle((114, 30), 6, 20, fill=False, ec=color, lw=1.0))\n    ax.add_patch(Arc((102, 40), 20, 20, angle=0, theta1=90, theta2=270, ec=color, lw=1.0))\n    ax.scatter([108], [40], s=8, color=color)\n\n\ndef plot_attack_type_quality(summary: pd.DataFrame) -> None:\n    plot_df = summary.sort_values("mean_xg", ascending=True)\n    labels = plot_df["attack_type"].astype(str).map(ATTACK_LABELS).to_list()\n    y = np.arange(len(plot_df))\n\n    fig, axes = plt.subplots(1, 2, figsize=(13, 6), gridspec_kw={"width_ratios": [1, 1.3]})\n    axes[0].barh(y, plot_df["shots"], color=vt.BAR_MUTED)\n    axes[0].set_yticks(y, labels)\n    axes[0].set_xlabel("슈팅 수")\n    axes[0].set_title("표본 수")\n    for yi, v in zip(y, plot_df["shots"]):\n        axes[0].text(v + 3, yi, f"{int(v)}", va="center", fontsize=9)\n\n    err_low = plot_df["mean_xg"] - plot_df["ci_low"]\n    err_high = plot_df["ci_high"] - plot_df["mean_xg"]\n    axes[1].barh(y, plot_df["mean_xg"], xerr=[err_low, err_high], color=vt.BAR)\n    axes[1].set_yticks(y, labels)\n    axes[1].set_xlabel("슈팅당 평균 xG")\n    axes[1].set_title("공격 유형별 평균 xG")\n    axes[1].axvline(summary["mean_xg"].mean(), color=vt.MUTED, lw=1, ls="--", alpha=0.8)\n    for yi, v, n in zip(y, plot_df["mean_xg"], plot_df["shots"]):\n        axes[1].text(v + 0.004, yi, f"{v:.3f}", va="center", fontsize=9)\n\n    fig.suptitle("공격 유형별 슈팅 수와 평균 xG", fontsize=14, y=0.98)\n    fig.tight_layout()\n    vt.apply_theme(fig)\n    vt.save_dark(fig, OUT_DIR / "01_attack_type_quality.png")\n    plt.close(fig)\n\n\ndef plot_adjusted_residuals(model_df: pd.DataFrame) -> pd.DataFrame:\n    residual_summary = mean_ci(model_df, "attack_type", "xg_adj_residual")\n    residual_summary["attack_type"] = pd.Categorical(\n        residual_summary["attack_type"], categories=ATTACK_ORDER, ordered=True\n    )\n    residual_summary = residual_summary.sort_values("mean", ascending=True)\n\n    y = np.arange(len(residual_summary))\n    fig, ax = plt.subplots(figsize=(9, 6))\n    colors = [vt.NEGATIVE if v < 0 else vt.LIME for v in residual_summary["mean"]]\n    err_low = residual_summary["mean"] - residual_summary["ci_low"]\n    err_high = residual_summary["ci_high"] - residual_summary["mean"]\n    ax.barh(\n        y,\n        residual_summary["mean"],\n        xerr=[err_low, err_high],\n        color=colors,\n        alpha=0.9,\n    )\n    ax.axvline(0, color=vt.MUTED, lw=1)\n    ax.set_yticks(y, residual_summary["attack_type"].astype(str).map(ATTACK_LABELS))\n    ax.set_xlabel("위치와 압박 통제 후 평균 잔차 xG")\n    ax.set_title("공격 유형별 잔차 xG")\n    max_abs = max(\n        abs(float(residual_summary["ci_low"].min())),\n        abs(float(residual_summary["ci_high"].max())),\n    )\n    ax.set_xlim(-max_abs * 1.25, max_abs * 1.25)\n    for yi, v, n in zip(y, residual_summary["mean"], residual_summary["count"]):\n        ha = "left" if v >= 0 else "right"\n        offset = 0.002 if v >= 0 else -0.002\n        ax.text(\n            v + offset,\n            yi,\n            f"{v:+.3f} (n={int(n)})",\n            va="center",\n            ha=ha,\n            fontsize=9,\n            bbox={"facecolor": vt.PANEL2, "edgecolor": vt.GRID, "alpha": 0.82, "pad": 1.5},\n        )\n    fig.tight_layout()\n    vt.apply_theme(fig)\n    vt.save_dark(fig, OUT_DIR / "02_adjusted_residual_xg.png")\n    plt.close(fig)\n    return residual_summary\n\n\ndef plot_pressure_distance_heatmap(work: pd.DataFrame) -> pd.DataFrame:\n    table = (\n        work.groupby(["shot_distance_bin", "nearest_def_bin"], observed=False)\n        .agg(shots=("shot_id", "size"), mean_xg=("xg", "mean"), goal_rate=("is_goal", "mean"))\n        .reset_index()\n    )\n    pivot = table.pivot(index="shot_distance_bin", columns="nearest_def_bin", values="mean_xg")\n    counts = table.pivot(index="shot_distance_bin", columns="nearest_def_bin", values="shots")\n\n    fig, ax = plt.subplots(figsize=(9, 4.8))\n    values = pivot.to_numpy(dtype=float)\n    im = ax.imshow(values, cmap=vt.XG_CMAP, aspect="auto", vmin=np.nanmin(values), vmax=np.nanmax(values))\n    ax.set_xticks(np.arange(pivot.shape[1]), pivot.columns.astype(str))\n    ax.set_yticks(np.arange(pivot.shape[0]), pivot.index.astype(str))\n    ax.set_xlabel("가장 가까운 수비수 거리")\n    ax.set_ylabel("슈팅 거리")\n    ax.set_title("슈팅 거리와 수비수 거리별 평균 xG")\n    for i in range(pivot.shape[0]):\n        for j in range(pivot.shape[1]):\n            val = pivot.iloc[i, j]\n            n = counts.iloc[i, j]\n            if not np.isnan(val):\n                ax.text(j, i, f"{val:.3f}\\nn={int(n)}", ha="center", va="center", fontsize=9)\n    fig.colorbar(im, ax=ax, label="평균 xG")\n    fig.tight_layout()\n    vt.apply_theme(fig)\n    vt.save_dark(fig, OUT_DIR / "03_pressure_distance_heatmap.png")\n    plt.close(fig)\n    return table\n\n\ndef plot_last_pass_quality(summary: pd.DataFrame) -> None:\n    plot_df = summary.sort_values("mean_xg", ascending=True)\n    y = np.arange(len(plot_df))\n    fig, ax = plt.subplots(figsize=(9, 5))\n    ax.barh(y, plot_df["mean_xg"], color=vt.BAR)\n    ax.set_yticks(y, plot_df["last_pass_type_filled"].astype(str).map(LAST_PASS_LABELS))\n    ax.set_xlabel("슈팅당 평균 xG")\n    ax.set_title("마지막 패스 유형별 평균 xG")\n    for yi, v, n in zip(y, plot_df["mean_xg"], plot_df["shots"]):\n        ax.text(v + 0.004, yi, f"{v:.3f} (n={int(n)})", va="center", fontsize=9)\n    fig.tight_layout()\n    vt.apply_theme(fig)\n    vt.save_dark(fig, OUT_DIR / "04_last_pass_quality.png")\n    plt.close(fig)\n\n\ndef plot_attack_type_profile(summary: pd.DataFrame) -> None:\n    plot_df = summary[summary["attack_type"].astype(str) != "set_piece"].copy()\n    plot_df["label"] = plot_df["attack_type"].astype(str).map(ATTACK_LABELS)\n    sizes = 60 + (plot_df["shots"] / plot_df["shots"].max()) * 900\n\n    fig, ax = plt.subplots(figsize=(9, 6))\n    sc = ax.scatter(\n        plot_df["avg_shot_dist_m"],\n        plot_df["avg_nearest_def_m"],\n        s=sizes,\n        c=plot_df["mean_xg"],\n        cmap=vt.XG_CMAP,\n        alpha=0.78,\n        edgecolor=vt.TEXT,\n        linewidth=0.8,\n    )\n    for _, row in plot_df.iterrows():\n        ax.text(\n            row["avg_shot_dist_m"] + 0.15,\n            row["avg_nearest_def_m"] + 0.03,\n            row["label"],\n            fontsize=9,\n        )\n    ax.set_xlabel("평균 슈팅 거리(m)")\n    ax.set_ylabel("평균 가장 가까운 수비수 거리(m)")\n    ax.set_title("오픈플레이 공격 유형별 슈팅 거리, 압박, xG")\n    cb = fig.colorbar(sc, ax=ax)\n    cb.set_label("평균 xG")\n    ax.margins(x=0.12, y=0.18)\n    fig.tight_layout()\n    vt.apply_theme(fig)\n    vt.save_dark(fig, OUT_DIR / "05_attack_type_context_bubble.png")\n    plt.close(fig)\n\n\ndef plot_pitch_small_multiples(df: pd.DataFrame) -> None:\n    selected = [\n        "cutback",\n        "central_penetration",\n        "wide_cross",\n        "fast_counter",\n        "slow_possession",\n        "set_piece",\n    ]\n    fig, axes = plt.subplots(2, 3, figsize=(13, 8))\n    for ax, attack_type in zip(axes.flat, selected):\n        draw_pitch(ax)\n        subset = df[df["attack_type"] == attack_type]\n        ax.scatter(\n            subset["shot_x"],\n            subset["shot_y"],\n            s=20 + subset["xg"] * 240,\n            c=subset["xg"],\n            cmap=vt.XG_CMAP,\n            vmin=0,\n            vmax=df["xg"].quantile(0.98),\n            alpha=0.72,\n            edgecolor=vt.TEXT,\n            linewidth=0.25,\n        )\n        label = ATTACK_LABELS.get(attack_type, attack_type)\n        ax.set_title(f"{label} (n={len(subset)}, xG={subset[\'xg\'].mean():.3f})", fontsize=10)\n    fig.suptitle("공격 유형별 슈팅 위치: 점 크기와 색은 xG", fontsize=14)\n    fig.tight_layout()\n    vt.apply_theme(fig)\n    vt.save_dark(fig, OUT_DIR / "06_pitch_shot_locations.png")\n    plt.close(fig)\n\n\ndef save_text_summary(df: pd.DataFrame, attack_summary: pd.DataFrame, residual_summary: pd.DataFrame) -> None:\n    residual_sorted = residual_summary.sort_values("mean", ascending=False).copy()\n    top_attack = attack_summary.sort_values("mean_xg", ascending=False).iloc[0]\n    top_residual = residual_sorted.iloc[0]\n    meta = {\n        "rows": int(len(df)),\n        "goals": int(df["is_goal"].sum()),\n        "mean_xg": float(df["xg"].mean()),\n        "total_xg": float(df["xg"].sum()),\n        "overall_goal_rate": float(df["is_goal"].mean()),\n        "has_360_rate": float(df["has_360_frame"].mean()),\n        "last_pass_missing_rate": float(df["last_pass_type"].isna().mean()),\n        "highest_raw_mean_xg_attack_type": {\n            "attack_type": str(top_attack["attack_type"]),\n            "mean_xg": float(top_attack["mean_xg"]),\n            "shots": int(top_attack["shots"]),\n        },\n        "highest_adjusted_residual_attack_type": {\n            "attack_type": str(top_residual["attack_type"]),\n            "mean_residual_xg": float(top_residual["mean"]),\n            "shots": int(top_residual["count"]),\n        },\n    }\n    with (OUT_DIR / "eda_key_metrics.json").open("w", encoding="utf-8") as f:\n        json.dump(meta, f, ensure_ascii=False, indent=2)\n\n\ndef main() -> None:\n    set_korean_plot_style()\n    ensure_out_dir()\n    df = pd.read_csv(DATA_PATH)\n    work = add_bins(df)\n\n    attack_summary = summarize_attack_types(df)\n    last_pass_summary = summarize_last_pass(df)\n    model_df = baseline_adjusted_residuals(df)\n\n    attack_summary.to_csv(OUT_DIR / "attack_type_summary.csv", index=False)\n    last_pass_summary.to_csv(OUT_DIR / "last_pass_summary.csv", index=False)\n\n    plot_attack_type_quality(attack_summary)\n    residual_summary = plot_adjusted_residuals(model_df)\n    residual_summary.to_csv(OUT_DIR / "adjusted_residual_summary.csv", index=False)\n    pressure_table = plot_pressure_distance_heatmap(work)\n    pressure_table.to_csv(OUT_DIR / "pressure_distance_summary.csv", index=False)\n    plot_last_pass_quality(last_pass_summary)\n    plot_attack_type_profile(attack_summary)\n    plot_pitch_small_multiples(df)\n    save_text_summary(df, attack_summary, residual_summary)\n\n    print(f"Wrote EDA outputs to {OUT_DIR.resolve()}")\n    print(attack_summary.to_string(index=False))\n    print()\n    print(last_pass_summary.to_string(index=False))\n\n\nif __name__ == "__main__":\n    main()\n'

# ---- bundled source: eda_high_level_questions.py ----
_EDA_HIGH_LEVEL_QUESTIONS_SOURCE = 'from pathlib import Path\nfrom itertools import combinations\nimport json\nimport math\n\nimport numpy as np\nimport pandas as pd\n\nimport matplotlib\n\nmatplotlib.use("Agg")\nimport matplotlib.pyplot as plt\nfrom matplotlib.colors import LinearSegmentedColormap\nfrom matplotlib.lines import Line2D\nfrom matplotlib.patches import Arc, Rectangle\n\nimport viz_theme as vt\n\n\nDATA_PATH = Path("wc2022_shots.csv")\nOUT_DIR = Path("outputs") / "wc2022_high_level_analysis"\nRANDOM_SEED = 26\n\nATTACK_ORDER = [\n    "cutback",\n    "central_penetration",\n    "wide_cross",\n    "fast_counter",\n    "high_turnover",\n    "slow_possession",\n    "set_piece",\n    "other",\n]\n\nLAST_PASS_ORDER = [\n    "through_ball",\n    "cross",\n    "cutback",\n    "central_pass",\n    "other",\n    "no_key_pass",\n]\n\nATTACK_LABELS = {\n    "cutback": "컷백",\n    "central_penetration": "중앙 침투",\n    "wide_cross": "와이드 크로스",\n    "fast_counter": "빠른 역습",\n    "high_turnover": "높은 위치 탈취",\n    "slow_possession": "긴 점유",\n    "set_piece": "세트피스",\n    "other": "기타",\n}\n\nLAST_PASS_LABELS = {\n    "through_ball": "스루패스",\n    "cross": "크로스",\n    "cutback": "컷백",\n    "central_pass": "중앙 패스",\n    "other": "기타",\n    "no_key_pass": "키패스 없음",\n}\n\nMODEL_LABELS = {\n    "M0 mean only": "M0 평균만",\n    "M1 shot location": "M1 슈팅 위치",\n    "M2 + shot context": "M2 + 슈팅 맥락",\n    "M3 + pressure": "M3 + 압박",\n    "M4 + build-up": "M4 + 공격 전개",\n    "M5 + attack labels": "M5 + 공격 유형",\n}\n\nBLOCK_LABELS = {\n    "shot_location": "슈팅 위치",\n    "shot_context": "슈팅 맥락",\n    "pressure": "수비/골키퍼 압박",\n    "build_up": "공격 전개",\n    "attack_labels": "공격 유형 라벨",\n}\n\nTEAM_LABELS = {\n    "Argentina": "아르헨티나",\n    "Australia": "호주",\n    "Belgium": "벨기에",\n    "Brazil": "브라질",\n    "Cameroon": "카메룬",\n    "Canada": "캐나다",\n    "Costa Rica": "코스타리카",\n    "Croatia": "크로아티아",\n    "Denmark": "덴마크",\n    "Ecuador": "에콰도르",\n    "England": "잉글랜드",\n    "France": "프랑스",\n    "Germany": "독일",\n    "Ghana": "가나",\n    "Iran": "이란",\n    "Japan": "일본",\n    "Korea Republic": "대한민국",\n    "Mexico": "멕시코",\n    "Morocco": "모로코",\n    "Netherlands": "네덜란드",\n    "Poland": "폴란드",\n    "Portugal": "포르투갈",\n    "Qatar": "카타르",\n    "Saudi Arabia": "사우디아라비아",\n    "Senegal": "세네갈",\n    "Serbia": "세르비아",\n    "Spain": "스페인",\n    "Switzerland": "스위스",\n    "Tunisia": "튀니지",\n    "United States": "미국",\n    "Uruguay": "우루과이",\n    "Wales": "웨일스",\n}\n\n\ndef set_korean_plot_style() -> None:\n    plt.rcParams["font.family"] = ["Malgun Gothic", "Noto Sans KR", "DejaVu Sans"]\n    plt.rcParams["axes.unicode_minus"] = False\n\n\ndef draw_attacking_half_pitch(ax) -> None:\n    line_color = vt.GRID\n    ax.set_xlim(60, 121)\n    ax.set_ylim(-1, 81)\n    ax.set_aspect("equal")\n    ax.axis("off")\n    ax.add_patch(Rectangle((60, 0), 60, 80, fill=False, ec=line_color, lw=1.1))\n    ax.plot([120, 120], [36, 44], color=line_color, lw=3)\n    ax.add_patch(Rectangle((102, 18), 18, 44, fill=False, ec=line_color, lw=1.1))\n    ax.add_patch(Rectangle((114, 30), 6, 20, fill=False, ec=line_color, lw=1.1))\n    ax.add_patch(Arc((102, 40), 20, 20, angle=0, theta1=90, theta2=270, ec=line_color, lw=1.1))\n    ax.scatter([108], [40], s=10, color=line_color)\n    ax.text(119.2, 40, "골문", ha="right", va="center", fontsize=8, color=vt.MUTED)\n\n\ndef ensure_out_dir() -> None:\n    OUT_DIR.mkdir(parents=True, exist_ok=True)\n\n\ndef shot_angle(row: pd.Series) -> float:\n    x = float(row["shot_x"])\n    y = float(row["shot_y"])\n    left = np.hypot(120 - x, 36 - y)\n    right = np.hypot(120 - x, 44 - y)\n    goal_width = 8.0\n    denom = 2 * left * right\n    if denom == 0:\n        return np.pi\n    cos_val = (left * left + right * right - goal_width * goal_width) / denom\n    return float(np.arccos(np.clip(cos_val, -1, 1)))\n\n\ndef prepare(df: pd.DataFrame) -> pd.DataFrame:\n    work = df.copy()\n    work["last_pass_type_filled"] = work["last_pass_type"].fillna("no_key_pass")\n    work["first_time_num"] = work["first_time"].fillna(False).astype(int)\n    work["under_pressure_num"] = work["under_pressure"].fillna(False).astype(int)\n    work["shot_y_abs_center"] = (work["shot_y"] - 40).abs()\n    work["shot_dist_sq"] = work["shot_dist_to_goal_m"] ** 2\n    work["shot_angle"] = work.apply(shot_angle, axis=1)\n    work["close_shot"] = (work["shot_dist_to_goal_m"] < 12).astype(int)\n    work["clean_lane"] = (work["def_between_ball_goal"] <= 1).astype(int)\n    work["separation_2m"] = (work["nearest_def_dist_m"] >= 2).astype(int)\n    work["distance_bin"] = pd.cut(\n        work["shot_dist_to_goal_m"],\n        bins=[0, 12, 20, np.inf],\n        labels=["근거리(<12m)", "중거리(12-20m)", "장거리(20m+)"],\n        right=False,\n    )\n    work["nearest_def_bin"] = pd.cut(\n        work["nearest_def_dist_m"],\n        bins=[0, 1, 2, 3, 5, np.inf],\n        labels=["0-1m", "1-2m", "2-3m", "3-5m", "5m+"],\n        right=False,\n    )\n    speed_values = work["progression_speed"].replace([np.inf, -np.inf], np.nan)\n    valid_speed = speed_values.dropna()\n    q = valid_speed.quantile([0, 0.25, 0.5, 0.75, 1]).to_numpy()\n    q = np.unique(q)\n    speed_labels = ["1분위(느림)", "2분위", "3분위", "4분위(빠름)"]\n    work["speed_quartile"] = pd.cut(\n        speed_values,\n        bins=q,\n        include_lowest=True,\n        labels=speed_labels[: len(q) - 1],\n    )\n    return work\n\n\ndef make_design(\n    df: pd.DataFrame,\n    numeric_cols: list[str],\n    categorical_cols: list[str],\n) -> pd.DataFrame:\n    pieces = []\n    for col in numeric_cols:\n        series = pd.to_numeric(df[col], errors="coerce")\n        pieces.append(series.fillna(series.median()).rename(col))\n    for col in categorical_cols:\n        filled = df[col].astype("object").where(df[col].notna(), "missing")\n        dummies = pd.get_dummies(filled, prefix=col, drop_first=False, dtype=float)\n        pieces.append(dummies)\n    if not pieces:\n        return pd.DataFrame(index=df.index)\n    return pd.concat(pieces, axis=1).astype(float)\n\n\ndef ridge_fit_predict(\n    x_train: np.ndarray,\n    y_train: np.ndarray,\n    x_test: np.ndarray,\n    ridge: float = 1e-6,\n) -> np.ndarray:\n    train_mean = x_train.mean(axis=0)\n    train_std = x_train.std(axis=0)\n    train_std[train_std == 0] = 1\n    z_train = (x_train - train_mean) / train_std\n    z_test = (x_test - train_mean) / train_std\n    z_train = np.column_stack([np.ones(len(z_train)), z_train])\n    z_test = np.column_stack([np.ones(len(z_test)), z_test])\n    penalty = np.eye(z_train.shape[1]) * ridge\n    penalty[0, 0] = 0\n    xtx = z_train.T @ z_train + penalty\n    xty = z_train.T @ y_train\n    try:\n        beta = np.linalg.solve(xtx, xty)\n    except np.linalg.LinAlgError:\n        beta = np.linalg.pinv(xtx) @ xty\n    return z_test @ beta\n\n\ndef cv_score(df: pd.DataFrame, design: pd.DataFrame, k: int = 5) -> dict:\n    rng = np.random.default_rng(RANDOM_SEED)\n    indices = np.arange(len(df))\n    rng.shuffle(indices)\n    folds = np.array_split(indices, k)\n    y = df["xg"].to_numpy(dtype=float)\n    x = design.to_numpy(dtype=float)\n    sse_model = 0.0\n    sse_base = 0.0\n    abs_err = []\n    for fold in folds:\n        train_idx = np.setdiff1d(indices, fold, assume_unique=False)\n        pred = ridge_fit_predict(x[train_idx], y[train_idx], x[fold])\n        baseline = y[train_idx].mean()\n        sse_model += float(((y[fold] - pred) ** 2).sum())\n        sse_base += float(((y[fold] - baseline) ** 2).sum())\n        abs_err.extend(np.abs(y[fold] - pred).tolist())\n    return {\n        "cv_r2": 1 - sse_model / sse_base,\n        "rmse": float(np.sqrt(sse_model / len(df))),\n        "mae": float(np.mean(abs_err)),\n    }\n\n\ndef xg_model_blocks() -> list[dict]:\n    return [\n        {\n            "block": "shot_location",\n            "model": "M1 shot location",\n            "numeric": [\n                "shot_dist_to_goal_m",\n                "shot_dist_sq",\n                "shot_x",\n                "shot_y_abs_center",\n                "shot_angle",\n            ],\n            "categorical": [],\n            "interpretation": "where the shot was taken",\n        },\n        {\n            "block": "shot_context",\n            "model": "M2 + shot context",\n            "numeric": ["first_time_num"],\n            "categorical": ["body_part", "shot_type"],\n            "interpretation": "body part, first-time, set-piece/open play",\n        },\n        {\n            "block": "pressure",\n            "model": "M3 + pressure",\n            "numeric": [\n                "nearest_def_dist_m",\n                "def_within_1m",\n                "def_within_2m",\n                "def_within_3m",\n                "def_in_box",\n                "def_between_ball_goal",\n                "teammates_in_box",\n                "gk_dist_from_goalline_m",\n                "gk_lateral_offset_m",\n                "under_pressure_num",\n            ],\n            "categorical": [],\n            "interpretation": "defender and goalkeeper context",\n        },\n        {\n            "block": "build_up",\n            "model": "M4 + build-up",\n            "numeric": [\n                "attack_start_x",\n                "attack_start_y",\n                "attack_duration_s",\n                "n_pass",\n                "n_carry",\n                "x_progression",\n                "goal_dist_gain",\n                "progression_speed",\n            ],\n            "categorical": ["attack_path"],\n            "interpretation": "speed, progression, route",\n        },\n        {\n            "block": "attack_labels",\n            "model": "M5 + attack labels",\n            "numeric": [],\n            "categorical": ["attack_type", "last_pass_type_filled", "play_pattern"],\n            "interpretation": "named tactical categories",\n        },\n    ]\n\n\ndef score_blocks(df: pd.DataFrame, blocks: list[dict]) -> dict:\n    numeric_cols: list[str] = []\n    categorical_cols: list[str] = []\n    for block in blocks:\n        numeric_cols += block["numeric"]\n        categorical_cols += block["categorical"]\n    y = df["xg"].to_numpy(dtype=float)\n    if not numeric_cols and not categorical_cols:\n        return {\n            "cv_r2": 0.0,\n            "rmse": float(np.sqrt(((y - y.mean()) ** 2).mean())),\n            "mae": float(np.abs(y - y.mean()).mean()),\n        }\n    design = make_design(df, numeric_cols, categorical_cols)\n    return cv_score(df, design)\n\n\ndef nested_model_scores(df: pd.DataFrame) -> pd.DataFrame:\n    blocks = [\n        {\n            "block": "baseline",\n            "model": "M0 mean only",\n            "numeric": [],\n            "categorical": [],\n            "interpretation": "baseline",\n        },\n        *xg_model_blocks(),\n    ]\n    rows = []\n    accumulated: list[dict] = []\n    for block in blocks:\n        accumulated.append(block)\n        score = score_blocks(df, accumulated)\n        rows.append(\n            {\n                "block": block["block"],\n                "model": block["model"],\n                "added_block": block["interpretation"],\n                **score,\n            }\n        )\n    out = pd.DataFrame(rows)\n    out["delta_cv_r2"] = out["cv_r2"].diff().fillna(out["cv_r2"])\n    return out\n\n\ndef block_order_averaged_contribution(df: pd.DataFrame) -> pd.DataFrame:\n    blocks = xg_model_blocks()\n    n_blocks = len(blocks)\n    by_name = {block["block"]: block for block in blocks}\n    block_names = tuple(by_name)\n    subset_scores: dict[tuple[str, ...], float] = {}\n\n    for r in range(n_blocks + 1):\n        for subset in combinations(block_names, r):\n            selected = [by_name[name] for name in subset]\n            subset_scores[tuple(sorted(subset))] = score_blocks(df, selected)["cv_r2"]\n\n    full_key = tuple(sorted(block_names))\n    full_cv_r2 = subset_scores[full_key]\n    rows = []\n    factorial_n = math.factorial(n_blocks)\n    for block_name in block_names:\n        shapley = 0.0\n        other_names = [name for name in block_names if name != block_name]\n        for r in range(n_blocks):\n            weight = math.factorial(r) * math.factorial(n_blocks - r - 1) / factorial_n\n            for subset in combinations(other_names, r):\n                subset_key = tuple(sorted(subset))\n                with_key = tuple(sorted((*subset, block_name)))\n                shapley += weight * (subset_scores[with_key] - subset_scores[subset_key])\n        without_key = tuple(sorted(other_names))\n        rows.append(\n            {\n                "block": block_name,\n                "block_label": BLOCK_LABELS[block_name],\n                "order_averaged_cv_r2": shapley,\n                "leave_one_block_out_drop": full_cv_r2 - subset_scores[without_key],\n                "full_model_cv_r2": full_cv_r2,\n            }\n        )\n    return pd.DataFrame(rows).sort_values("order_averaged_cv_r2", ascending=False)\n\n\ndef fit_full_prediction(\n    df: pd.DataFrame,\n    numeric_cols: list[str],\n    categorical_cols: list[str],\n) -> np.ndarray:\n    design = make_design(df, numeric_cols, categorical_cols)\n    x = design.to_numpy(dtype=float)\n    y = df["xg"].to_numpy(dtype=float)\n    return ridge_fit_predict(x, y, x)\n\n\ndef group_summary(df: pd.DataFrame, group_col: str, value_col: str) -> pd.DataFrame:\n    grouped = df.groupby(group_col, observed=False)[value_col]\n    out = grouped.agg(["count", "mean", "std"]).reset_index()\n    out["se"] = out["std"] / np.sqrt(out["count"].clip(lower=1))\n    out["ci_low"] = out["mean"] - 1.96 * out["se"]\n    out["ci_high"] = out["mean"] + 1.96 * out["se"]\n    return out\n\n\ndef controlled_residuals(df: pd.DataFrame) -> pd.DataFrame:\n    controls_num = [\n        "shot_dist_to_goal_m",\n        "shot_dist_sq",\n        "shot_x",\n        "shot_y_abs_center",\n        "shot_angle",\n        "first_time_num",\n        "nearest_def_dist_m",\n        "def_within_1m",\n        "def_within_2m",\n        "def_within_3m",\n        "def_in_box",\n        "def_between_ball_goal",\n        "teammates_in_box",\n        "gk_dist_from_goalline_m",\n        "gk_lateral_offset_m",\n        "under_pressure_num",\n    ]\n    controls_cat = ["body_part", "shot_type"]\n    work = df.copy()\n    work["xg_control_pred"] = fit_full_prediction(work, controls_num, controls_cat)\n    work["xg_control_resid"] = work["xg"] - work["xg_control_pred"]\n    return work\n\n\ndef attack_control_summary(df: pd.DataFrame) -> pd.DataFrame:\n    raw = group_summary(df, "attack_type", "xg").rename(\n        columns={"mean": "raw_mean_xg", "ci_low": "raw_ci_low", "ci_high": "raw_ci_high"}\n    )\n    adj = group_summary(df, "attack_type", "xg_control_resid").rename(\n        columns={\n            "mean": "controlled_residual_xg",\n            "ci_low": "controlled_ci_low",\n            "ci_high": "controlled_ci_high",\n        }\n    )\n    detail = (\n        df.groupby("attack_type", observed=False)\n        .agg(\n            shots=("shot_id", "size"),\n            goals=("is_goal", "sum"),\n            goal_rate=("is_goal", "mean"),\n            close_shot_rate=("close_shot", "mean"),\n            clean_lane_rate=("clean_lane", "mean"),\n            separation_2m_rate=("separation_2m", "mean"),\n            avg_shot_dist_m=("shot_dist_to_goal_m", "mean"),\n            avg_nearest_def_m=("nearest_def_dist_m", "mean"),\n            avg_def_between=("def_between_ball_goal", "mean"),\n            avg_duration_s=("attack_duration_s", "mean"),\n            avg_progression_speed=("progression_speed", "mean"),\n        )\n        .reset_index()\n    )\n    out = detail.merge(\n        raw[["attack_type", "raw_mean_xg", "raw_ci_low", "raw_ci_high"]],\n        on="attack_type",\n        how="left",\n    ).merge(\n        adj[["attack_type", "controlled_residual_xg", "controlled_ci_low", "controlled_ci_high"]],\n        on="attack_type",\n        how="left",\n    )\n    out["attack_type"] = pd.Categorical(out["attack_type"], ATTACK_ORDER, ordered=True)\n    return out.sort_values("attack_type")\n\n\ndef last_pass_control_summary(df: pd.DataFrame) -> pd.DataFrame:\n    raw = group_summary(df, "last_pass_type_filled", "xg").rename(\n        columns={"mean": "raw_mean_xg"}\n    )\n    adj = group_summary(df, "last_pass_type_filled", "xg_control_resid").rename(\n        columns={"mean": "controlled_residual_xg"}\n    )\n    detail = (\n        df.groupby("last_pass_type_filled", observed=False)\n        .agg(\n            shots=("shot_id", "size"),\n            goals=("is_goal", "sum"),\n            goal_rate=("is_goal", "mean"),\n            close_shot_rate=("close_shot", "mean"),\n            clean_lane_rate=("clean_lane", "mean"),\n            separation_2m_rate=("separation_2m", "mean"),\n            avg_shot_dist_m=("shot_dist_to_goal_m", "mean"),\n            avg_nearest_def_m=("nearest_def_dist_m", "mean"),\n            avg_def_between=("def_between_ball_goal", "mean"),\n            avg_last_pass_x=("last_pass_x", "mean"),\n        )\n        .reset_index()\n    )\n    out = detail.merge(\n        raw[["last_pass_type_filled", "raw_mean_xg"]],\n        on="last_pass_type_filled",\n        how="left",\n    ).merge(\n        adj[["last_pass_type_filled", "controlled_residual_xg"]],\n        on="last_pass_type_filled",\n        how="left",\n    )\n    out["last_pass_type_filled"] = pd.Categorical(\n        out["last_pass_type_filled"], LAST_PASS_ORDER, ordered=True\n    )\n    return out.sort_values("last_pass_type_filled")\n\n\ndef pressure_regression(df: pd.DataFrame) -> pd.DataFrame:\n    y = df["xg"].to_numpy(dtype=float)\n    models = [\n        ("bivariate nearest defender", ["nearest_def_dist_m"], []),\n        (\n            "+ shot location",\n            [\n                "nearest_def_dist_m",\n                "shot_dist_to_goal_m",\n                "shot_dist_sq",\n                "shot_x",\n                "shot_y_abs_center",\n                "shot_angle",\n            ],\n            [],\n        ),\n        (\n            "+ full pressure context",\n            [\n                "nearest_def_dist_m",\n                "shot_dist_to_goal_m",\n                "shot_dist_sq",\n                "shot_x",\n                "shot_y_abs_center",\n                "shot_angle",\n                "def_within_1m",\n                "def_within_2m",\n                "def_within_3m",\n                "def_in_box",\n                "def_between_ball_goal",\n                "gk_dist_from_goalline_m",\n                "gk_lateral_offset_m",\n            ],\n            ["body_part", "shot_type"],\n        ),\n    ]\n    rows = []\n    for name, numeric, categorical in models:\n        design = make_design(df, numeric, categorical)\n        x = design.to_numpy(dtype=float)\n        mean = x.mean(axis=0)\n        std = x.std(axis=0)\n        std[std == 0] = 1\n        z = (x - mean) / std\n        z = np.column_stack([np.ones(len(z)), z])\n        beta = np.linalg.pinv(z.T @ z) @ z.T @ y\n        pred = z @ beta\n        r2 = 1 - ((y - pred) ** 2).sum() / ((y - y.mean()) ** 2).sum()\n        nearest_idx = list(design.columns).index("nearest_def_dist_m")\n        rows.append(\n            {\n                "model": name,\n                "nearest_def_coef_per_1sd": beta[nearest_idx + 1],\n                "r2_in_sample": r2,\n            }\n        )\n    return pd.DataFrame(rows)\n\n\ndef speed_pressure_summary(df: pd.DataFrame) -> pd.DataFrame:\n    return (\n        df.dropna(subset=["speed_quartile"])\n        .groupby(["speed_quartile", "nearest_def_bin"], observed=False)\n        .agg(\n            shots=("shot_id", "size"),\n            mean_xg=("xg", "mean"),\n            close_shot_rate=("close_shot", "mean"),\n            clean_lane_rate=("clean_lane", "mean"),\n            avg_shot_dist_m=("shot_dist_to_goal_m", "mean"),\n        )\n        .reset_index()\n    )\n\n\ndef pressure_distance_summary(df: pd.DataFrame) -> pd.DataFrame:\n    return (\n        df.groupby(["distance_bin", "nearest_def_bin"], observed=False)\n        .agg(\n            shots=("shot_id", "size"),\n            mean_xg=("xg", "mean"),\n            goal_rate=("is_goal", "mean"),\n            clean_lane_rate=("clean_lane", "mean"),\n        )\n        .reset_index()\n    )\n\n\ndef team_style_summary(df: pd.DataFrame) -> pd.DataFrame:\n    counts = df.groupby(["team", "attack_type"], observed=False).size().unstack(fill_value=0)\n    for col in ATTACK_ORDER:\n        if col not in counts.columns:\n            counts[col] = 0\n    shares = counts[ATTACK_ORDER].div(counts[ATTACK_ORDER].sum(axis=1), axis=0)\n    summary = (\n        df.groupby("team")\n        .agg(\n            shots=("shot_id", "size"),\n            goals=("is_goal", "sum"),\n            total_xg=("xg", "sum"),\n            mean_xg=("xg", "mean"),\n            avg_duration_s=("attack_duration_s", "mean"),\n            avg_progression_speed=("progression_speed", "mean"),\n        )\n        .join(shares.add_prefix("share_"))\n        .reset_index()\n    )\n    summary["direct_share"] = summary["share_fast_counter"] + summary["share_high_turnover"]\n    summary["wide_cross_share"] = summary["share_wide_cross"]\n    summary["central_share"] = summary["share_central_penetration"] + summary["share_cutback"]\n    return summary.sort_values("mean_xg", ascending=False)\n\n\ndef plot_model_blocks(scores: pd.DataFrame, block_importance: pd.DataFrame) -> None:\n    fig, axes = plt.subplots(1, 2, figsize=(14.2, 5.7))\n    ax = axes[0]\n    y = np.arange(len(scores))\n    labels = scores["model"].map(MODEL_LABELS)\n    bars = ax.barh(y, scores["cv_r2"], color=vt.BAR)\n    ax.set_yticks(y, labels)\n    ax.invert_yaxis()\n    ax.set_xlabel("5-fold CV R²")\n    ax.set_title("지정 순서로 누적한 모델")\n    ax.axvline(0, color=vt.MUTED, lw=1)\n    ax.grid(axis="x", color=vt.GRID, linewidth=0.8, alpha=0.8)\n    ax.set_axisbelow(True)\n    ax.set_xlim(0, max(0.9, scores["cv_r2"].max() + 0.13))\n    for rect, val, delta in zip(bars, scores["cv_r2"], scores["delta_cv_r2"]):\n        ax.text(\n            rect.get_width() + 0.012,\n            rect.get_y() + rect.get_height() / 2,\n            f"{val:.3f}  (Δ{delta:+.3f})",\n            ha="left",\n            va="center",\n            fontsize=9.2,\n        )\n    ax.spines[["top", "right"]].set_visible(False)\n\n    imp = block_importance.sort_values("order_averaged_cv_r2")\n    y2 = np.arange(len(imp))\n    colors = [vt.LIME if v >= 0 else vt.NEGATIVE for v in imp["order_averaged_cv_r2"]]\n    bars2 = axes[1].barh(y2, imp["order_averaged_cv_r2"], color=colors)\n    axes[1].set_yticks(y2, imp["block_label"])\n    axes[1].set_xlabel("평균 한계 CV R²")\n    axes[1].set_title("모든 블록 순서 평균 기여도")\n    axes[1].axvline(0, color=vt.MUTED, lw=1)\n    axes[1].grid(axis="x", color=vt.GRID, linewidth=0.8, alpha=0.8)\n    axes[1].set_axisbelow(True)\n    max_abs = max(0.08, float(np.abs(imp["order_averaged_cv_r2"]).max()) + 0.03)\n    axes[1].set_xlim(min(0, float(imp["order_averaged_cv_r2"].min()) - 0.02), max_abs)\n    for rect, val in zip(bars2, imp["order_averaged_cv_r2"]):\n        ha = "left" if val >= 0 else "right"\n        offset = 0.006 if val >= 0 else -0.006\n        axes[1].text(\n            val + offset,\n            rect.get_y() + rect.get_height() / 2,\n            f"{val:+.3f}",\n            ha=ha,\n            va="center",\n            fontsize=9.2,\n        )\n    axes[1].spines[["top", "right"]].set_visible(False)\n    fig.suptitle("xG 설명력: 순서 의존성과 순서 평균 기여도를 함께 확인", fontsize=14)\n    fig.text(\n        0.5,\n        0.02,\n        "왼쪽 Δ는 지정한 순서의 증가분이고, 오른쪽은 가능한 블록 순서를 모두 평균낸 기여도",\n        ha="center",\n        fontsize=9,\n        color=vt.MUTED,\n    )\n    fig.tight_layout()\n    fig.subplots_adjust(bottom=0.15, top=0.86)\n    vt.apply_theme(fig)\n    vt.save_dark(fig, OUT_DIR / "01_model_block_cv_r2.png")\n    plt.close(fig)\n\n\ndef plot_attack_raw_adjusted(summary: pd.DataFrame) -> None:\n    plot_df = summary.sort_values("raw_mean_xg")\n    y = np.arange(len(plot_df))\n    fig, axes = plt.subplots(1, 2, figsize=(13, 5.8), sharey=True)\n    axes[0].barh(y, plot_df["raw_mean_xg"], color=vt.BAR)\n    axes[0].set_yticks(y, plot_df["attack_type"].astype(str).map(ATTACK_LABELS))\n    axes[0].set_xlabel("원자료 평균 xG")\n    axes[0].set_title("통제 전")\n    for yi, val, n in zip(y, plot_df["raw_mean_xg"], plot_df["shots"]):\n        axes[0].text(val + 0.004, yi, f"{val:.3f} (n={int(n)})", va="center", fontsize=8.8)\n    colors = [vt.LIME if v >= 0 else vt.NEGATIVE for v in plot_df["controlled_residual_xg"]]\n    axes[1].barh(y, plot_df["controlled_residual_xg"], color=colors)\n    axes[1].axvline(0, color=vt.MUTED, lw=1)\n    axes[1].set_xlabel("평균 잔차 xG")\n    axes[1].set_title("슈팅 위치와 압박 통제 후")\n    for yi, val in zip(y, plot_df["controlled_residual_xg"]):\n        ha = "left" if val >= 0 else "right"\n        offset = 0.002 if val >= 0 else -0.002\n        axes[1].text(val + offset, yi, f"{val:+.3f}", va="center", ha=ha, fontsize=8.8)\n    fig.suptitle("공격 유형 효과는 슈팅 조건을 넘어 남는가?", fontsize=14)\n    fig.tight_layout()\n    vt.apply_theme(fig)\n    vt.save_dark(fig, OUT_DIR / "02_attack_type_raw_vs_controlled.png")\n    plt.close(fig)\n\n\ndef plot_speed_pressure_heatmap(summary: pd.DataFrame) -> None:\n    pivot = summary.pivot(index="speed_quartile", columns="nearest_def_bin", values="mean_xg")\n    counts = summary.pivot(index="speed_quartile", columns="nearest_def_bin", values="shots")\n    close = summary.pivot(index="speed_quartile", columns="nearest_def_bin", values="close_shot_rate")\n    fig, ax = plt.subplots(figsize=(9.5, 5.2))\n    data = pivot.to_numpy(dtype=float)\n    xg_cmap = vt.XG_CMAP\n    im = ax.imshow(data, cmap=xg_cmap, aspect="auto", vmin=np.nanmin(data), vmax=np.nanmax(data))\n    ax.set_xticks(np.arange(pivot.shape[1]), pivot.columns.astype(str))\n    ax.set_yticks(np.arange(pivot.shape[0]), pivot.index.astype(str))\n    ax.set_xlabel("가장 가까운 수비수 거리")\n    ax.set_ylabel("전진 속도 분위")\n    ax.set_title("빠른 전개는 좋은 슈팅 조건을 만들 때 효과가 커진다")\n    for i in range(pivot.shape[0]):\n        for j in range(pivot.shape[1]):\n            val = pivot.iloc[i, j]\n            n = counts.iloc[i, j]\n            c = close.iloc[i, j]\n            if pd.notna(val):\n                r, g, b, _ = im.cmap(im.norm(val))\n                luminance = 0.2126 * r + 0.7152 * g + 0.0722 * b\n                text_color = vt.TEXT\n                ax.text(\n                    j,\n                    i,\n                    f"{val:.3f}\\n{int(n)}개, 근거리 {c:.0%}",\n                    ha="center",\n                    va="center",\n                    fontsize=8.3,\n                    color=text_color,\n                    fontweight="medium",\n                )\n    fig.colorbar(im, ax=ax, label="평균 xG")\n    fig.tight_layout()\n    vt.apply_theme(fig)\n    vt.save_dark(fig, OUT_DIR / "03_speed_pressure_heatmap.png")\n    plt.close(fig)\n\n\ndef plot_pressure_distance_lines(summary: pd.DataFrame) -> None:\n    fig, ax = plt.subplots(figsize=(9, 5.2))\n    for distance_bin, subset in summary.groupby("distance_bin", observed=False):\n        subset = subset.sort_values("nearest_def_bin")\n        ax.plot(\n            subset["nearest_def_bin"].astype(str),\n            subset["mean_xg"],\n            marker="o",\n            label=str(distance_bin),\n        )\n        for _, row in subset.iterrows():\n            ax.text(\n                str(row["nearest_def_bin"]),\n                row["mean_xg"] + 0.006,\n                f"{int(row[\'shots\'])}개",\n                ha="center",\n                fontsize=8,\n            )\n    ax.set_xlabel("가장 가까운 수비수 거리")\n    ax.set_ylabel("평균 xG")\n    ax.set_title("슈팅 거리를 나누면 압박 효과가 다르게 보인다")\n    ax.legend(title="슈팅 거리")\n    fig.tight_layout()\n    vt.apply_theme(fig)\n    vt.save_dark(fig, OUT_DIR / "04_pressure_distance_interaction.png")\n    plt.close(fig)\n\n\ndef plot_last_pass_mechanism(summary: pd.DataFrame) -> None:\n    plot_df = summary.sort_values("raw_mean_xg")\n    y = np.arange(len(plot_df))\n    fig, axes = plt.subplots(1, 2, figsize=(14.2, 5.7))\n    axes[0].barh(y, plot_df["raw_mean_xg"], color=vt.BAR)\n    axes[0].set_yticks(y, plot_df["last_pass_type_filled"].astype(str))\n    axes[0].set_yticks(y, plot_df["last_pass_type_filled"].astype(str).map(LAST_PASS_LABELS))\n    axes[0].set_xlabel("원자료 평균 xG")\n    axes[0].set_title("평균 xG")\n    for yi, val, n in zip(y, plot_df["raw_mean_xg"], plot_df["shots"]):\n        axes[0].text(val + 0.004, yi, f"{val:.3f} (n={int(n)})", va="center", fontsize=8.8)\n    bubble_size = 90 + plot_df["shots"] / plot_df["shots"].max() * 520\n    scatter = axes[1].scatter(\n        plot_df["close_shot_rate"],\n        plot_df["separation_2m_rate"],\n        s=bubble_size,\n        c=plot_df["raw_mean_xg"],\n        cmap=vt.XG_CMAP,\n        alpha=0.82,\n        edgecolor=vt.TEXT,\n    )\n    label_offsets = {\n        "through_ball": (18, 8, "left"),\n        "cross": (-28, 10, "right"),\n        "cutback": (16, -12, "left"),\n        "central_pass": (20, 8, "left"),\n        "other": (14, 8, "left"),\n        "no_key_pass": (20, -12, "left"),\n    }\n    for _, row in plot_df.iterrows():\n        pass_type = str(row["last_pass_type_filled"])\n        dx, dy, ha = label_offsets.get(pass_type, (16, 8, "left"))\n        axes[1].annotate(\n            LAST_PASS_LABELS.get(pass_type, pass_type),\n            xy=(row["close_shot_rate"], row["separation_2m_rate"]),\n            xytext=(dx, dy),\n            textcoords="offset points",\n            fontsize=8.8,\n            ha=ha,\n            va="center",\n            bbox=dict(facecolor=vt.PANEL2, edgecolor=vt.GRID, alpha=0.72, pad=1.1),\n        )\n    axes[1].set_xlabel("12m 미만 근거리 슈팅 비율")\n    axes[1].set_ylabel("수비수와 2m 이상 떨어진 슈팅 비율")\n    axes[1].set_title("마지막 패스별 슈팅 조건: 근거리 진입 × 압박 회피")\n    x_max = min(0.84, plot_df["close_shot_rate"].max() + 0.10)\n    y_max = min(0.82, plot_df["separation_2m_rate"].max() + 0.10)\n    axes[1].set_xlim(0, x_max)\n    axes[1].set_ylim(0.25, y_max)\n    cbar = fig.colorbar(scatter, ax=axes[1], fraction=0.046, pad=0.035)\n    cbar.set_label("평균 xG")\n    size_examples = [50, 200, 400]\n    size_handles = [\n        axes[1].scatter(\n            [],\n            [],\n            s=90 + n / plot_df["shots"].max() * 520,\n            facecolors="none",\n            edgecolors=vt.MUTED,\n            label=f"n={n}",\n        )\n        for n in size_examples\n    ]\n    axes[1].legend(\n        handles=size_handles,\n        title="원 크기 = 슈팅 수",\n        loc="upper right",\n        frameon=True,\n        fontsize=8,\n        title_fontsize=8.5,\n        labelspacing=1.6,\n        handleheight=2.0,\n        borderpad=0.8,\n    )\n    fig.suptitle("마지막 패스는 무엇을 바꾸는가?", fontsize=14)\n    fig.tight_layout()\n    vt.apply_theme(fig)\n    vt.save_dark(fig, OUT_DIR / "05_last_pass_mechanism.png")\n    plt.close(fig)\n\n\ndef plot_last_pass_pitch_map(df: pd.DataFrame) -> None:\n    selected = ["through_ball", "cross", "cutback", "central_pass"]\n    fig, axes = plt.subplots(2, 2, figsize=(12.5, 9.5))\n    vmax = df["xg"].quantile(0.98)\n\n    for ax, pass_type in zip(axes.flat, selected):\n        subset = df[df["last_pass_type_filled"] == pass_type].dropna(\n            subset=["last_pass_x", "last_pass_y", "shot_x", "shot_y"]\n        )\n        draw_attacking_half_pitch(ax)\n        for _, row in subset.iterrows():\n            ax.plot(\n                [row["last_pass_x"], row["shot_x"]],\n                [row["last_pass_y"], row["shot_y"]],\n                color=vt.MUTED,\n                alpha=0.13,\n                lw=0.8,\n                zorder=1,\n            )\n        ax.scatter(\n            subset["last_pass_x"],\n            subset["last_pass_y"],\n            s=16,\n            color=vt.GOLD,\n            marker="x",\n            alpha=0.74,\n            linewidth=0.75,\n            label="패스 시작",\n            zorder=2,\n        )\n        sc = ax.scatter(\n            subset["shot_x"],\n            subset["shot_y"],\n            s=18 + subset["xg"] * 260,\n            c=subset["xg"],\n            cmap=vt.XG_CMAP,\n            vmin=0,\n            vmax=vmax,\n            alpha=0.86,\n            edgecolor=vt.TEXT,\n            linewidth=0.35,\n            label="슈팅 위치",\n            zorder=3,\n        )\n        label = LAST_PASS_LABELS.get(pass_type, pass_type)\n        ax.set_title(\n            f"{label}: 평균 xG {subset[\'xg\'].mean():.3f}",\n            fontsize=11,\n        )\n\n    legend_handles = [\n        Line2D(\n            [],\n            [],\n            color=vt.GOLD,\n            marker="x",\n            linestyle="None",\n            markersize=8,\n            markeredgewidth=1.6,\n            label="패스 시작",\n        ),\n        Line2D(\n            [],\n            [],\n            color=vt.TEXT,\n            marker="o",\n            markerfacecolor=vt.LIME,\n            markeredgecolor=vt.TEXT,\n            linestyle="None",\n            markersize=11,\n            label="슈팅 위치",\n        ),\n    ]\n    legend = fig.legend(\n        handles=legend_handles,\n        loc="lower center",\n        ncol=2,\n        frameon=True,\n        fontsize=11,\n        handletextpad=0.9,\n        columnspacing=2.8,\n        borderpad=0.7,\n    )\n    legend.get_frame().set_facecolor(vt.PANEL)\n    legend.get_frame().set_edgecolor(vt.GRID)\n    legend.get_frame().set_alpha(0.95)\n    for text in legend.get_texts():\n        text.set_color(vt.TEXT)\n    fig.colorbar(sc, ax=axes.ravel().tolist(), shrink=0.72, label="xG")\n    fig.suptitle("마지막 패스 유형별 패스 시작 위치와 슈팅 위치", fontsize=15, y=0.97)\n    vt.apply_theme(fig)\n    vt.save_dark(fig, OUT_DIR / "07_last_pass_pitch_map.png")\n    plt.close(fig)\n\n\ndef plot_team_style(summary: pd.DataFrame) -> None:\n    plot_df = summary[summary["shots"] >= 25].copy()\n    fig, ax = plt.subplots(figsize=(10.2, 6.0))\n    sc = ax.scatter(\n        plot_df["direct_share"],\n        plot_df["mean_xg"],\n        s=55 + plot_df["shots"] * 5.4,\n        c=plot_df["wide_cross_share"],\n        cmap=vt.XG_CMAP,\n        alpha=0.78,\n        edgecolor=vt.TEXT,\n    )\n    top = pd.concat(\n        [\n            plot_df.nlargest(4, "mean_xg"),\n            plot_df.nlargest(3, "shots"),\n            plot_df.nlargest(3, "direct_share"),\n        ]\n    ).drop_duplicates("team")\n    label_offsets = {\n        "Switzerland": (14, 10, "left"),\n        "England": (18, 12, "left"),\n        "Netherlands": (18, 4, "left"),\n        "Germany": (14, -16, "left"),\n        "France": (-48, 24, "right"),\n        "Argentina": (24, 22, "left"),\n        "Brazil": (-40, -24, "right"),\n        "Iran": (-16, 12, "right"),\n        "Australia": (16, 8, "left"),\n    }\n    for _, row in top.iterrows():\n        dx, dy, ha = label_offsets.get(row["team"], (14, 8, "left"))\n        ax.annotate(\n            TEAM_LABELS.get(row["team"], row["team"]),\n            xy=(row["direct_share"], row["mean_xg"]),\n            xytext=(dx, dy),\n            textcoords="offset points",\n            fontsize=8.5,\n            ha=ha,\n            va="center",\n            bbox=dict(facecolor=vt.PANEL2, edgecolor=vt.GRID, alpha=0.72, pad=1.1),\n            arrowprops=dict(arrowstyle="-", color=vt.MUTED, lw=0.6, shrinkA=0, shrinkB=4),\n        )\n    ax.set_xlabel("직접 공격 비중(빠른 역습 + 높은 위치 탈취)")\n    ax.set_ylabel("슈팅당 평균 xG")\n    ax.set_title("팀별 공격 스타일은 보이지만 표본 수 제약이 있다")\n    ax.margins(x=0.08, y=0.10)\n    cb = fig.colorbar(sc, ax=ax)\n    cb.set_label("와이드 크로스 비중")\n    fig.tight_layout()\n    vt.apply_theme(fig)\n    vt.save_dark(fig, OUT_DIR / "06_team_style_quality.png")\n    plt.close(fig)\n\n\ndef write_report(\n    scores: pd.DataFrame,\n    attack: pd.DataFrame,\n    last_pass: pd.DataFrame,\n    pressure_coef: pd.DataFrame,\n    team: pd.DataFrame,\n) -> None:\n    top_raw = attack.sort_values("raw_mean_xg", ascending=False).iloc[0]\n    top_control = attack.sort_values("controlled_residual_xg", ascending=False).iloc[0]\n    top_last = last_pass.sort_values("raw_mean_xg", ascending=False).iloc[0]\n    pressure_bi = pressure_coef.iloc[0]\n    pressure_full = pressure_coef.iloc[-1]\n    model_best = scores.iloc[-1]\n\n    text = f"""# 수준 높은 분석 질문과 EDA 결과\n\n## 내가 추천하는 핵심 질문\n\n**좋은 공격은 특정 전술 유형 그 자체에서 나오는가, 아니면 그 전술이 더 좋은 슈팅 조건(가까운 위치, 깨끗한 슈팅 경로, 수비수와의 분리)을 만들어서 좋아 보이는가?**\n\n이 질문이 가장 수준 높은 이유는 단순 평균 비교가 아니라 **메커니즘**을 묻기 때문이다. `attack_type`의 평균 xG를 보고 끝내지 않고, 슈팅 위치와 수비 압박을 통제한 뒤에도 차이가 남는지 확인한다.\n\n## 핵심 질문 1\n\n**공격 유형의 xG 차이는 전술 효과인가, 슈팅 조건의 결과인가?**\n\n- 원자료 평균 xG 1위: `{top_raw[\'attack_type\']}` = {top_raw[\'raw_mean_xg\']:.3f}\n- 위치와 압박 통제 후 잔차 xG 1위: `{top_control[\'attack_type\']}` = {top_control[\'controlled_residual_xg\']:+.3f}\n- 해석: 공격 유형 간 raw xG 차이는 존재하지만, 상당 부분은 그 유형이 만들어낸 슈팅 위치와 수비 상황으로 설명된다.\n\n![Attack raw vs controlled](02_attack_type_raw_vs_controlled.png)\n\n## 핵심 질문 2\n\n**xG를 설명하는 정보는 공격 전개 변수보다 슈팅 위치와 압박 변수에 더 많이 들어 있는가?**\n\n- 최종 nested model의 5-fold CV R2: {model_best[\'cv_r2\']:.3f}\n- 각 블록의 추가 설명력은 `01_model_block_cv_r2.png`에 표시했다.\n- 해석: 공격 전개 변수는 중요하지만, xG의 직접 설명력은 슈팅 위치와 슈팅 순간 압박 맥락에서 크게 나온다. 그래서 좋은 공격은 \'전개 방식\'보다 \'전개가 만들어낸 최종 조건\'으로 평가해야 한다.\n\n![Model blocks](01_model_block_cv_r2.png)\n\n## 핵심 질문 3\n\n**빠른 전개는 언제 좋은 공격이 되는가?**\n\n- 빠른 전개 자체보다, 빠른 전개가 가까운 슈팅과 수비수 분리까지 같이 만들 때 xG가 높아진다.\n- 속도 분위와 가장 가까운 수비수 거리 구간을 동시에 보면, 같은 빠른 전개 안에서도 close-shot 비율에 따라 평균 xG가 달라진다.\n\n![Speed pressure](03_speed_pressure_heatmap.png)\n\n## 핵심 질문 4\n\n**수비 압박은 xG를 낮추는가, 아니면 좋은 위치에서 자연스럽게 동반되는가?**\n\n- 가장 가까운 수비수 거리의 단순 계수: {pressure_bi[\'nearest_def_coef_per_1sd\']:+.4f}\n- 슈팅 위치와 압박 맥락 통제 후 계수: {pressure_full[\'nearest_def_coef_per_1sd\']:+.4f}\n- 해석: 수비 압박은 단순히 \'가까우면 나쁘다\'로 해석하면 안 된다. 가까운 슈팅일수록 수비수도 가까운 경우가 많기 때문에 거리 구간을 나누거나 위치를 통제해야 한다.\n\n![Pressure distance](04_pressure_distance_interaction.png)\n\n## 보조 메커니즘 분석\n\n**마지막 패스는 좋은 공격에서 어떤 메커니즘으로 작동하는가?**\n\n- raw 평균 xG 1위 마지막 패스: `{top_last[\'last_pass_type_filled\']}` = {top_last[\'raw_mean_xg\']:.3f}\n- 해석: 마지막 패스는 공격 유형 분석을 독립적으로 재검증하는 변수가 아니라, 가까운 슈팅 비율과 수비수와의 분리 공간을 얼마나 만드는지 설명하는 보조 메커니즘으로 읽어야 한다.\n\n![Last pass mechanism](05_last_pass_mechanism.png)\n\n## 결론\n\n이 프로젝트의 결론은 이렇게 잡는 것이 좋다.\n\n> 2022 월드컵에서 좋은 공격은 특정 전술 이름 하나로 결정되지 않는다. 좋은 공격은 전개 과정을 통해 더 가까운 슈팅 위치, 더 깨끗한 슈팅 경로, 수비수와의 분리 공간을 만들어내는 공격이다. 따라서 공격 전개 변수는 직접적인 결과라기보다, 최종 슈팅 조건을 만들어내는 과정 변수로 해석해야 한다.\n"""\n    (OUT_DIR / "high_level_report.md").write_text(text, encoding="utf-8")\n\n\ndef main() -> None:\n    set_korean_plot_style()\n    ensure_out_dir()\n    raw = pd.read_csv(DATA_PATH)\n    df = prepare(raw)\n    scores = nested_model_scores(df)\n    block_importance = block_order_averaged_contribution(df)\n    residual_df = controlled_residuals(df)\n    attack = attack_control_summary(residual_df)\n    last_pass = last_pass_control_summary(residual_df)\n    pressure_coef = pressure_regression(df)\n    speed_pressure = speed_pressure_summary(df)\n    pressure_distance = pressure_distance_summary(df)\n    team = team_style_summary(df)\n\n    scores.to_csv(OUT_DIR / "model_block_scores.csv", index=False)\n    block_importance.to_csv(OUT_DIR / "model_block_order_averaged_contribution.csv", index=False)\n    attack.to_csv(OUT_DIR / "attack_type_controlled_summary.csv", index=False)\n    last_pass.to_csv(OUT_DIR / "last_pass_controlled_summary.csv", index=False)\n    pressure_coef.to_csv(OUT_DIR / "pressure_regression_coefficients.csv", index=False)\n    speed_pressure.to_csv(OUT_DIR / "speed_pressure_summary.csv", index=False)\n    pressure_distance.to_csv(OUT_DIR / "pressure_distance_summary.csv", index=False)\n    team.to_csv(OUT_DIR / "team_style_summary.csv", index=False)\n\n    plot_model_blocks(scores, block_importance)\n    plot_attack_raw_adjusted(attack)\n    plot_speed_pressure_heatmap(speed_pressure)\n    plot_pressure_distance_lines(pressure_distance)\n    plot_last_pass_mechanism(last_pass)\n    plot_last_pass_pitch_map(residual_df)\n    plot_team_style(team)\n    write_report(scores, attack, last_pass, pressure_coef, team)\n\n    key_metrics = {\n        "rows": int(len(df)),\n        "goals": int(df["is_goal"].sum()),\n        "mean_xg": float(df["xg"].mean()),\n        "best_raw_attack_type": str(attack.sort_values("raw_mean_xg", ascending=False).iloc[0]["attack_type"]),\n        "best_raw_attack_mean_xg": float(attack.sort_values("raw_mean_xg", ascending=False).iloc[0]["raw_mean_xg"]),\n        "best_last_pass_type": str(last_pass.sort_values("raw_mean_xg", ascending=False).iloc[0]["last_pass_type_filled"]),\n        "best_last_pass_mean_xg": float(last_pass.sort_values("raw_mean_xg", ascending=False).iloc[0]["raw_mean_xg"]),\n        "final_cv_r2": float(scores.iloc[-1]["cv_r2"]),\n    }\n    (OUT_DIR / "high_level_key_metrics.json").write_text(\n        json.dumps(key_metrics, ensure_ascii=False, indent=2),\n        encoding="utf-8",\n    )\n    print(f"Wrote high-level analysis outputs to {OUT_DIR.resolve()}")\n    print(scores.to_string(index=False))\n    print()\n    print(attack.sort_values("raw_mean_xg", ascending=False).to_string(index=False))\n    print()\n    print(last_pass.sort_values("raw_mean_xg", ascending=False).to_string(index=False))\n    print()\n    print(pressure_coef.to_string(index=False))\n\n\nif __name__ == "__main__":\n    main()\n'

